def feature(id, title, summary, output, inputs, maintenance, temporal, sources, *, app_area, layers=("structural",), caution="", backend=False):
    return Node(id, title, "App features", "Feature", summary, output, inputs,
                maintenance, temporal, sources, layers, caution, area="feature",
                feature_type="backend" if backend else "interactive", app_area=app_area)


